-- Migration 0010 — mission members, and one holder per mission token (spec §0 "Mission
-- member", "Mission token"; §7.9 bis; §8 "the token used and its holder"; ADR
-- mission-members-and-per-holder-tokens).
--
-- A mission had one active token, shared by whoever worked on it: a call was attributed
-- to the mission and to whatever label the caller declared. A mission now has one or
-- more tokens, each with one holder:
--
--   member token   generated by a member of the mission for themselves
--   named token    created by the creator for something that has no account
--
-- 1. `mission_members` — the users the creator gave access to the mission. The creator
--    is a member by construction and has no row: `missions.creator_user_id` says it.
--    One row per (mission, user): removing sets `removed_at`, adding again clears it.
--
-- 2. `mission_tokens` is rebuilt with its holder: `kind`, `holder_user_id` (member
--    tokens), `name` (named tokens), `created_by`, `last_used_at`. The table is rebuilt
--    rather than altered because the rule "a member token has a holder and no name, a
--    named token a name and no holder" is a CHECK over several columns, and the "one
--    active token per mission" index becomes "one active token per holder". Nothing
--    references this table.
--
--    Every existing token becomes a member token of the mission's creator, with the
--    same id, prefix, hash and status: a Bearer in use keeps working, nothing is
--    re-issued.
--
-- 3. `audit` and `events` record who called: the token and its holder (a user id for a
--    member token, the name for a named one). Entries written before this migration
--    keep NULL there: the audit is append-only (its triggers refuse the UPDATE a
--    backfill would need), and the truth about those calls is that the instance did
--    not know which holder made them.
--
-- Portable SQL: plain tables, partial unique indexes and `ALTER TABLE … RENAME TO`
-- (SQLite and Postgres both). `STRICT` is SQLite's.

-------------------------------------------------------------------------------
-- 1. Members
-------------------------------------------------------------------------------

CREATE TABLE mission_members (
  mission_id  TEXT NOT NULL REFERENCES missions (id) ON DELETE CASCADE,
  user_id     TEXT NOT NULL REFERENCES users (id),
  added_by    TEXT NOT NULL REFERENCES users (id),
  added_at    TEXT NOT NULL,
  removed_at  TEXT,                           -- NULL while the user is a member
  PRIMARY KEY (mission_id, user_id)
) STRICT; -- sqlite: STRICT

-- "The missions shared with me".
CREATE INDEX mission_members_user ON mission_members (user_id, removed_at);

-------------------------------------------------------------------------------
-- 2. Tokens, each with one holder
-------------------------------------------------------------------------------

CREATE TABLE mission_tokens_with_holder (
  id              TEXT NOT NULL PRIMARY KEY,
  mission_id      TEXT NOT NULL REFERENCES missions (id) ON DELETE CASCADE,
  prefix          TEXT NOT NULL UNIQUE,       -- public lookup key, safe to log
  hash            TEXT NOT NULL,              -- hash of the secret part; the secret is stored nowhere
  hash_alg        TEXT NOT NULL,              -- e.g. 'argon2id'
  status          TEXT NOT NULL CHECK (status IN ('active', 'rotated', 'revoked')),
  kind            TEXT NOT NULL CHECK (kind IN ('member', 'named')),
  holder_user_id  TEXT REFERENCES users (id), -- member tokens: the member it belongs to
  name            TEXT,                       -- named tokens: the name the creator gave
  created_by      TEXT NOT NULL REFERENCES users (id),
  created_at      TEXT NOT NULL,
  retired_at      TEXT,
  last_used_at    TEXT,                       -- last call the door authenticated, to the minute
  CHECK (
    (kind = 'member' AND holder_user_id IS NOT NULL AND name IS NULL)
    OR (kind = 'named' AND holder_user_id IS NULL AND name IS NOT NULL AND name <> '')
  )
) STRICT; -- sqlite: STRICT

INSERT INTO mission_tokens_with_holder
  (id, mission_id, prefix, hash, hash_alg, status, kind, holder_user_id, name, created_by,
   created_at, retired_at, last_used_at)
SELECT t.id, t.mission_id, t.prefix, t.hash, t.hash_alg, t.status, 'member', m.creator_user_id,
       NULL, m.creator_user_id, t.created_at, t.retired_at, NULL
FROM mission_tokens t JOIN missions m ON m.id = t.mission_id;

DROP TABLE mission_tokens;
ALTER TABLE mission_tokens_with_holder RENAME TO mission_tokens;

-- At most one active token per member of a mission; generating again retires the previous row.
CREATE UNIQUE INDEX mission_tokens_one_active_per_member
  ON mission_tokens (mission_id, holder_user_id) WHERE status = 'active' AND kind = 'member';
-- A name identifies one active named token of a mission.
CREATE UNIQUE INDEX mission_tokens_one_active_per_name
  ON mission_tokens (mission_id, name) WHERE status = 'active' AND kind = 'named';
CREATE INDEX mission_tokens_mission ON mission_tokens (mission_id, created_at);
-- "Every active token this user holds" (deactivation).
CREATE INDEX mission_tokens_holder ON mission_tokens (holder_user_id, status);

-------------------------------------------------------------------------------
-- 3. Who called
-------------------------------------------------------------------------------

ALTER TABLE audit ADD COLUMN token_id TEXT;
ALTER TABLE audit ADD COLUMN token_kind TEXT;
ALTER TABLE audit ADD COLUMN token_holder TEXT;   -- a user id (member) or a token name (named)

-- The calls of one mission per holder, and the holder filter of the Audit page.
CREATE INDEX audit_mission_holder_ts ON audit (mission_id, token_kind, token_holder, ts);

-- Copies of `details_json.token_kind` / `.holder` of a call event, made by the sessions
-- repository at insert (as `agent_label` is, migration 0008), so the timeline of one
-- holder is an indexed read.
ALTER TABLE events ADD COLUMN token_kind TEXT;
ALTER TABLE events ADD COLUMN token_holder TEXT;

CREATE INDEX events_session_holder_ts ON events (session_id, token_kind, token_holder, ts, id);
